const gallery=document.querySelector('#gallery'),dialog=document.querySelector('#preview'),content=document.querySelector('#preview-content');let lastFocus;
const imageUrl=(id,w=700)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
function openDialog(){lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open')}
function render(filter='all'){gallery.replaceChildren();formats.filter(f=>filter==='all'||f.type===filter).forEach(f=>{const button=document.createElement('button');button.className='gallery-card';button.setAttribute('aria-label',`Preview ${f.title} — placeholder`);button.innerHTML=`<img loading="lazy" src="${imageUrl(f.image)}" alt="${f.title} illustrative placeholder"><span class="badge">GALLERY PREVIEW</span><span class="card-caption"><span><small>${f.label}</small>${f.title}</span><span class="arrow-circle">↗</span></span>`;button.addEventListener('click',()=>{content.innerHTML=`<img class="preview-image" src="${imageUrl(f.image,1200)}" alt="${f.title} placeholder"><div class="preview-label">VISUAL PLACEHOLDER · ${f.label.toUpperCase()}</div><h2>${f.title}</h2><p>${f.description} This is an illustrative photograph, not a FilmWizard-generated video.</p><a class="button" href="https://filmwizard.ai/register">Create with FilmWizard ↗</a>`;openDialog()});gallery.append(button)})}
render();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));
document.querySelector('#watch-demo').addEventListener('click',()=>{content.innerHTML='<h2 style="margin:0 0 20px">FilmWizard in action.</h2><iframe src="https://www.loom.com/embed/a5f75b4b78f8497ab40e7bd4de80740c?autoplay=0&hide_owner=true&hide_share=true" title="Film Wizard official introduction" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe><p>Official FilmWizard introduction. <a href="https://www.loom.com/share/a5f75b4b78f8497ab40e7bd4de80740c" target="_blank" rel="noopener">Open on Loom ↗</a></p>';openDialog()});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{content.replaceChildren();document.body.classList.remove('modal-open');lastFocus?.focus()});const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
// Lightweight, illustrative feature animation. No generation requests are made.
const stage=document.querySelector('.motion-stage'),typed=document.querySelector('#typed-prompt'),motionDemo=document.querySelector('.motion-demo'),toggle=document.querySelector('#motion-toggle');
const scenes={agent:{prompt:'Turn my idea into 3 brand videos',label:'ASK WIZARD AGENT',processing:'Building your creative workflow',description:'One request. Ideas, scripts and a creative workflow, all in one place.',caption:'One idea. More ways to tell your story.'},templates:{prompt:'Product reveal → add my brand',label:'CHOOSE A PROVEN FORMAT',processing:'Making the format your own',description:'Start with a proven format. Add your brand and reuse the process.',caption:'Pick a format. Make it yours. Repeat.'},remix:{prompt:'Paste a reference → make it mine',label:'REMIX WHAT ALREADY WORKS',processing:'Reworking your inspiration',description:'Turn an Instagram, YouTube or TikTok reference into your own branded content.',caption:'Your inspiration. Your brand. Your remix.'}};
let activeScene='agent',elapsed=0,lastTick=0,paused=false,inView=false;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function paintMotion(){const s=scenes[activeScene],t=elapsed%9600;stage.dataset.phase=reducedMotion.matches?'result':t<3200?'typing':t<5300?'processing':'result';typed.textContent=s.prompt.slice(0,Math.floor(t/65));}
function chooseScene(name){activeScene=name;elapsed=0;const s=scenes[name];stage.dataset.mode=name;document.querySelector('.prompt-label').textContent=s.label;document.querySelector('#processing-label').textContent=s.processing;document.querySelector('#scene-description').textContent=s.description;document.querySelector('.output-caption').textContent=s.caption;document.querySelectorAll('[data-scene]').forEach(b=>{const chosen=b.dataset.scene===name;b.setAttribute('aria-selected',String(chosen));b.tabIndex=chosen?0:-1});document.querySelector('#motion-panel').setAttribute('aria-labelledby','tab-'+name);paintMotion()}
const tabs=[...document.querySelectorAll('[data-scene]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>chooseScene(b.dataset.scene));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();chooseScene(tabs[next].dataset.scene)}})});
toggle.addEventListener('click',()=>{paused=!paused;motionDemo.classList.toggle('paused',paused);toggle.textContent=paused?'▶ Play':'Ⅱ Pause';toggle.setAttribute('aria-label',paused?'Play workflow animation':'Pause workflow animation')});
new IntersectionObserver(entries=>{inView=entries[0].isIntersecting},{threshold:.15}).observe(motionDemo);
function tick(now){if(lastTick&&inView&&!paused&&!document.hidden&&!reducedMotion.matches){elapsed+=Math.min(now-lastTick,100);paintMotion()}lastTick=now;requestAnimationFrame(tick)}chooseScene('agent');requestAnimationFrame(tick);
function setMotionPreference(){toggle.hidden=reducedMotion.matches;paintMotion()}reducedMotion.addEventListener('change',setMotionPreference);setMotionPreference();
let heroVisible=true,offerVisible=false;const sticky=document.querySelector('.sticky-offer');function updateSticky(){sticky.hidden=heroVisible||offerVisible}new IntersectionObserver(e=>{heroVisible=e[0].isIntersecting;updateSticky()}).observe(document.querySelector('.hero'));new IntersectionObserver(e=>{offerVisible=e[0].isIntersecting;updateSticky()},{threshold:.2}).observe(document.querySelector('.price-card'));
